        if (arguments.Length != 0) {
            if (!arguments.SequenceEqual(new[] { "--test-personal-observation-recovery" })) return 2;
            tests = tests.Where(test => test.Name.StartsWith("ObservationRecovery", StringComparison.Ordinal)).ToArray();
        }
        int passed = 0;
        int failed = 0;
        foreach (var test in tests) {
            try { await test.Run(); Console.WriteLine("PASS " + test.Name); passed++; }
            catch (Exception exception) { Console.Error.WriteLine("FAIL " + test.Name + ": " + exception); failed++; }
        }
        Console.WriteLine($"{passed}/{tests.Length} session regressions passed; {failed} failed");
        return failed == 0 ? 0 : 1;
